"""Result writing helpers for paper-protocol eval outputs."""

from __future__ import annotations

import csv
import json
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

import matplotlib.pyplot as plt
import numpy as np


@dataclass
class ArtifactManifest:
    """Collect local artifacts generated by a paper-eval run."""

    root: Path
    artifacts: list[dict] = field(default_factory=list)

    def add(self, key: str, path: Path, kind: str, logged_to_wandb: bool = False, **extra) -> None:
        try:
            rel = path.relative_to(self.root)
        except ValueError:
            rel = path
        item = {
            "key": key,
            "path": str(rel),
            "kind": kind,
            "logged_to_wandb": bool(logged_to_wandb),
        }
        item.update(extra)
        self.artifacts.append(item)

    def write(self, path: Path, metadata: dict[str, Any] | None = None) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        payload = {
            "root": str(self.root),
            "artifacts": self.artifacts,
        }
        if metadata:
            payload["metadata"] = metadata
        path.write_text(json.dumps(payload, indent=2, allow_nan=True), encoding="utf-8")


def ensure_output_dirs(outputs) -> None:
    for path in [
        outputs.root,
        outputs.tables_dir,
        outputs.figures_dir,
        outputs.data_dir,
        outputs.manifest_path.parent,
        outputs.json_path.parent,
    ]:
        Path(path).mkdir(parents=True, exist_ok=True)


def write_json(path: Path, payload: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2, allow_nan=True), encoding="utf-8")


def write_csv(path: Path, rows: list[dict]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    if not rows:
        path.write_text("", encoding="utf-8")
        return
    with path.open("w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=list(rows[0].keys()))
        writer.writeheader()
        writer.writerows(rows)


def save_figure(fig: plt.Figure, path: Path, dpi: int = 170) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fig.savefig(path, dpi=dpi, bbox_inches="tight")


def json_array(values) -> list:
    arr = np.asarray(values)
    return arr.astype(float).tolist()


def savez(path: Path, **arrays) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    np.savez_compressed(path, **arrays)
